import 'package:flutter/material.dart'; import '../models/user.dart'; import '../services/api.dart'; import 'home.dart'; import 'register.dart';
class Login extends StatefulWidget{const Login({super.key});@override State<Login> createState()=>_LoginState();}
class _LoginState extends State<Login>{final e=TextEditingController(),p=TextEditingController();bool loading=false,hide=true;@override void dispose(){e.dispose();p.dispose();super.dispose();}Future<void> go()async{if(e.text.trim().isEmpty||p.text.isEmpty)return _msg('Enter email and password');setState(()=>loading=true);try{final r=await Api.post('/auth/login',{'email':e.text.trim(),'password':p.text});await Api.save(r);if(!mounted)return;Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>Home(user:User.fromJson(Map<String,dynamic>.from(r['user'])))),(_)=>false);}catch(x){if(mounted)_msg(x.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}}void _msg(String x)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x)));@override Widget build(BuildContext c)=>_Shell(title:'Welcome back',subtitle:'Sign in to your student space',child:Column(children:[TextField(controller:e,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(prefixIcon:Icon(Icons.mail_outline),labelText:'Student email')),const SizedBox(height:14),TextField(controller:p,obscureText:hide,decoration:InputDecoration(prefixIcon:const Icon(Icons.lock_outline),labelText:'Password',suffixIcon:IconButton(onPressed:()=>setState(()=>hide=!hide),icon:Icon(hide?Icons.visibility:Icons.visibility_off)))),const SizedBox(height:22),SizedBox(width:double.infinity,height:54,child:FilledButton(onPressed:loading?null:go,child:loading?const CircularProgressIndicator():const Text('Enter Campus'))),const SizedBox(height:10),TextButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const Register())),child:const Text('Create student account'))]));}
class _Shell extends StatelessWidget{final String title,subtitle;final Widget child;const _Shell({required this.title,required this.subtitle,required this.child});@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(22),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:470),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.school_rounded,size:42),const SizedBox(height:24),Text('Student login',style:TextStyle(fontWeight:FontWeight.w800)),Text(title,style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:6),Text(subtitle),const SizedBox(height:28),child])))));}
